def _log_size(self) -> int:
    try:
        return self._log.path.stat().st_size
    except OSError:
        return 0

def _has_rows(self) -> bool:
    for table in ("facts", "ticks"):
        if self._db.execute(
            f"SELECT EXISTS(SELECT 1 FROM {table})"
        ).fetchone()[0]:
            return True
    return False
